//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\// 


    auto linear = +[](Scalar& output, Scalar input, Scalar alpha) noexcept 
    {
        output = input;
    };

    auto nonzero_diag = +[](Scalar& output, Scalar input, Scalar alpha) noexcept
    {
        //TODO: implement custom activation 'nonzero_diag'
        output = input; //default fallback
    };

    static constexpr Scalar kC0 = 0.044715;
    static constexpr Scalar kSqrt2PiInv = Scalar(0.7978845608028654);
    auto gelu = +[](Scalar& output, Scalar input, Scalar alpha) noexcept 
    {
        Scalar x3 = input * input * input;
        Scalar y  = kSqrt2PiInv * (input + kC0 * x3);
        output     = Scalar(0.5) * input * (Scalar(1) + std::tanh(y));
    };


//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\// 

    
    // model input and flattened
    constexpr int flat_size = 5858; 
    std::array<Scalar, flat_size> model_input;

    // normalize input
    for (int i = 0; i < 5858; i++) { model_input[i] = (initial_input[i] - input_min_mean[i]) / (input_norm_std[i]); } 

    if (model_input.size() != 5858) { throw std::invalid_argument("Invalid input size. Expected size: 5858"); }

    // Dense, layer 1
    static std::array<Scalar, 1> layer_1_output;
    Dense_MLP_LU<Scalar, 1>(
        layer_1_output.data(), model_input.data(),
        weights_1.data(), biases_1.data(),
        5858, linear, 0.0);

    // UnitNormalization, layer 2
    static std::array<Scalar, 1> layer_2_output;
    UnitNormalization_MLP_LU<Scalar, 1>(
        layer_2_output.data(), layer_1_output.data(),
        epsilon_2);

    // Activation, layer 3
    static std::array<Scalar, 1> layer_3_output;
    for (int i = 0; i < 1; ++i) {
        gelu(layer_3_output[i], layer_2_output[i], 0.0);
    }

    // Dense, layer 4
    static std::array<Scalar, 7652> layer_4_output;
    Dense_MLP_LU<Scalar, 7652>(
        layer_4_output.data(), layer_3_output.data(),
        weights_4.data(), biases_4.data(),
        1, linear, 0.0);

    // Activation, layer 5
    static std::array<Scalar, 7652> layer_5_output;
    for (int i = 0; i < 7652; ++i) {
        nonzero_diag(layer_5_output[i], layer_4_output[i], 0.0);
    }


//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\//\\// 


    static std::array<Scalar, 7652> model_output;

    for (int i = 0; i < 7652; i++) { model_output[i] = (layer_5_output[i] * output_norm_std[i]) + output_min_mean[i]; }

    return model_output;

